<x-layouts.app title="Activity log"><div class="page-heading"><div><span class="eyebrow">A CLEAR TRAIL OF THE DETAILS</span><h1>Activity log</h1><p class="subtle">Every saved change, together in one place.</p></div><span class="demo-pill">APPEND-ONLY HISTORY</span></div><section class="panel activity-list">@forelse($events as $event)<article class="activity-row"><span class="activity-symbol" aria-hidden="true">{{ str_contains($event->action, 'equipment') ? '▣' : '✓' }}</span><div><strong>{{ str_replace('_', ' ', ucfirst($event->action)) }}</strong><p>{{ $event->detail }}</p><small><a href="/workers/{{ $event->worker_id }}">{{ $event->worker->name }}</a> · {{ $event->actor->name }}</small></div><time datetime="{{ $event->created_at->toIso8601String() }}">{{ $event->created_at->format('M j, Y') }}<small>{{ $event->created_at->format('H:i:s') }} UTC</small></time></article>@empty<p class="empty-inline">No activity yet.</p>@endforelse</section>@if($events->hasPages())<nav class="simple-pagination" aria-label="Activity pages">@if($events->previousPageUrl())<a class="button secondary" href="{{ $events->previousPageUrl() }}">← Newer</a>@endif<span>Page {{ $events->currentPage() }} of {{ $events->lastPage() }}</span>@if($events->nextPageUrl())<a class="button secondary" href="{{ $events->nextPageUrl() }}">Older →</a>@endif</nav>@endif</x-layouts.app>
